{"command": "cd /tmp/opencode && python3 - <<'EOF'
import re, subprocess
out = subprocess.run(["pdftotext","/work/workspace/documents/month_05/bank_statement.pdf","-"],capture_output=True,text=True).stdout
lines=[l for l in out.splitlines() if l.strip()]
start=lines.index("Transactions")
tx_re=re.compile(r"^\d\d/\d\d/\d{4}$")
for i in range(start+1,len(lines)):
    if tx_re.match(lines[i]):
        print(i, repr(lines[i]), "| next:", repr(lines[i+1]) if i+1<len(lines) else None)
EOF"}

